-- Instalacion unica para el expediente Oracle. Ejecutar como DBA en XEPDB1.
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET ECHO OFF
SET DEFINE OFF
DECLARE n NUMBER; BEGIN
 IF SYS_CONTEXT('USERENV','CON_NAME') <> 'XEPDB1' THEN RAISE_APPLICATION_ERROR(-20060,'Se requiere XEPDB1'); END IF;
 SELECT COUNT(*) INTO n FROM dba_objects WHERE owner='RCONF_OWNER' AND object_name IN ('RCONF_PROJECT_DATA','V_PROJECT_DATA','PROJECT_API');
 IF n<>0 THEN RAISE_APPLICATION_ERROR(-20061,'Expediente existente: no repetir instalacion'); END IF;
END;
/
