DECLARE v CLOB; BEGIN
 DBMS_LOB.CREATETEMPORARY(v, TRUE);
 DBMS_LOB.WRITEAPPEND(v,LENGTH('{"target":3.1,"rows":{}}'),'{"target":3.1,"rows":{}}');
