CREATE VIEW rconf_owner.v_project_data AS SELECT doc_key,payload,version,updated_at FROM rconf_owner.rconf_project_data;
CREATE OR REPLACE PACKAGE rconf_owner.project_api AUTHID DEFINER AS
 PROCEDURE save_maturity(p_payload IN CLOB,p_version IN NUMBER,p_role IN VARCHAR2,p_new OUT NUMBER);
END project_api;
/
CREATE OR REPLACE PACKAGE BODY rconf_owner.project_api AS
 PROCEDURE save_maturity(p_payload IN CLOB,p_version IN NUMBER,p_role IN VARCHAR2,p_new OUT NUMBER) IS
 BEGIN
  IF p_role IS NULL OR p_role NOT IN ('analista','gestor') THEN RAISE_APPLICATION_ERROR(-20062,'Rol no autorizado'); END IF;
  IF p_payload IS NULL OR DBMS_LOB.GETLENGTH(p_payload)>60000 THEN RAISE_APPLICATION_ERROR(-20063,'Documento invalido'); END IF;
  UPDATE rconf_owner.rconf_project_data SET payload=p_payload,version=version+1,updated_at=SYSTIMESTAMP WHERE doc_key='MATURITY' AND version=p_version;
  IF SQL%ROWCOUNT<>1 THEN RAISE_APPLICATION_ERROR(-20064,'La matriz cambio; recargue antes de guardar'); END IF;
  p_new:=p_version+1;
 END;
END project_api;
/
SHOW ERRORS PACKAGE BODY rconf_owner.project_api
DECLARE n NUMBER; BEGIN
 SELECT COUNT(*) INTO n FROM dba_objects WHERE owner='RCONF_OWNER' AND object_name IN ('PROJECT_API','V_PROJECT_DATA') AND status <> 'VALID';
 IF n<>0 THEN RAISE_APPLICATION_ERROR(-20065,'Objeto invalido'); END IF;
END;
/
GRANT SELECT ON rconf_owner.v_project_data TO rconf_runtime,rconf_readonly;
GRANT EXECUTE ON rconf_owner.project_api TO rconf_runtime;
COMMIT;
